export const TEXT_DEFAULTS={font:'Arial',size:32,bold:false,italic:false,underline:false,align:'center',lineHeight:1.25};
export function paintText(ctx,text,style,{width,height,frameWidthMm,color}){
 const s={...TEXT_DEFAULTS,...style};const fontPx=s.size*25.4/72*(width/frameWidthMm);ctx.fillStyle=color;ctx.strokeStyle=color;ctx.font=(s.italic?'italic ':'')+(s.bold?'700 ':'400 ')+fontPx+'px '+s.font;ctx.textBaseline='alphabetic';ctx.textAlign='left';const maxWidth=width*.94,lineHeight=fontPx*s.lineHeight,lines=[];
 for(const paragraph of text.replaceAll('\r','').split('\n')){if(!paragraph){lines.push({text:'',last:true});continue}const words=paragraph.split(/\s+/);let line='';for(const word of words){const next=line?line+' '+word:word;if(ctx.measureText(next).width>maxWidth&&line){lines.push({text:line,last:false});line=word}else line=next}lines.push({text:line,last:true})}
 const total=lines.length*lineHeight,start=-total/2+fontPx*.8;
 lines.forEach((line,i)=>{const y=start+i*lineHeight,measured=ctx.measureText(line.text).width;let x=s.align==='center'?-measured/2:s.align==='right'?maxWidth/2-measured:-maxWidth/2;if(s.align==='justify'&&!line.last&&line.text.includes(' ')){const words=line.text.split(' '),ink=words.reduce((n,w)=>n+ctx.measureText(w).width,0),gap=(maxWidth-ink)/(words.length-1);x=-maxWidth/2;for(const word of words){ctx.fillText(word,x,y);x+=ctx.measureText(word).width+gap}if(s.underline){ctx.lineWidth=fontPx*.05;ctx.beginPath();ctx.moveTo(-maxWidth/2,y+fontPx*.12);ctx.lineTo(maxWidth/2,y+fontPx*.12);ctx.stroke()}}else{ctx.fillText(line.text,x,y);if(s.underline&&line.text){ctx.lineWidth=fontPx*.05;ctx.beginPath();ctx.moveTo(x,y+fontPx*.12);ctx.lineTo(x+measured,y+fontPx*.12);ctx.stroke()}}});return {overflow:total>height*.96||lines.some(l=>ctx.measureText(l.text).width>maxWidth)};
}
